import { describe, it, expect } from "vitest";
import { resolveInitCmd } from "@/app/console/lib/resumeClaude";

// #3937: `--continue` is emitted with a shell fallback, because a resume with no conversation exits 1
// having written ZERO bytes to stdout — which showed up as a dead `$` prompt rather than a failed
// command. Asserted as a constant so the three call sites stay in lockstep with resumeClaude.ts.
const CONTINUE_OR_FRESH = "claude --continue 2>/dev/null || claude";

/**
 * #36 / #1041: panes that had claude running auto-resume via `claude --continue` — but ONLY as crash
 * recovery (an unclean shutdown with auto-resume opted in, OR a banner "restore" click). A clean quit
 * leaves sessions dormant.
 */
// A LOCAL-MODEL pane resumes on ITS OWN harness. `HARNESS_PLACEHOLDERS` holds both `claude` and
// `bsc-agent`, and the resume arm used to answer the claude command for either — so a fleet stream
// wired to a local model (#173) resumed by launching CLAUDE, silently ignoring the configured model
// with nothing in the logs to say so. `bsc-agent` takes `--continue`/`-c` deliberately mirroring
// claude's (crates/bsc-agent/src/main.rs), so the command is DERIVED from the placeholder now.
const BSC_AGENT_CONTINUE = "bsc-agent --continue 2>/dev/null || bsc-agent";

describe("resolveInitCmd — the harness a resume comes back on", () => {
  const resuming = {
    startupPrompt: undefined as string | undefined,
    continueSession: true,
    paneWasClaude: true,
    autoResumeClaude: false,
    wasUncleanShutdown: false,
    restoreRequested: false,
  };

  it("resumes a bsc-agent pane on bsc-agent, never on claude", () => {
    expect(resolveInitCmd({ ...resuming, explicit: "bsc-agent" })).toBe(BSC_AGENT_CONTINUE);
  });

  it("still resumes a claude pane on claude — the default must not invert", () => {
    expect(resolveInitCmd({ ...resuming, explicit: "claude" })).toBe("claude --continue 2>/dev/null || claude");
  });

  it("leaves a REAL explicit command untouched, whichever harness is resuming", () => {
    // The placeholder rule applies only to the bare harness name; a caller that chose a real command
    // (`aider --message ...`, a wrapper script) must still win verbatim.
    expect(resolveInitCmd({ ...resuming, explicit: "aider --message go" })).toBe("aider --message go");
  });

  it("does not resume a bsc-agent pane that is not resuming — it launches fresh", () => {
    expect(resolveInitCmd({ ...resuming, continueSession: false, paneWasClaude: false, explicit: "bsc-agent" })).toBe("bsc-agent");
  });
});

describe("resolveInitCmd", () => {
  // A pane that had claude, the user opted into silent auto-resume, but a CLEAN shutdown + no restore.
  const base = {
    explicit: undefined as string | undefined,
    startupPrompt: undefined as string | undefined,
    continueSession: false,
    paneWasClaude: true,
    autoResumeClaude: true,
    wasUncleanShutdown: false,
    restoreRequested: false,
  };

  it("returns '' for a pane that has never run claude — bash prompt as usual", () => {
    expect(resolveInitCmd({ ...base, paneWasClaude: false, wasUncleanShutdown: true })).toBe("");
  });

  it("does NOT auto-resume after a CLEAN shutdown, even with the toggle on (#1041)", () => {
    expect(resolveInitCmd({ ...base })).toBe("");
  });

  it("silently resumes after an UNCLEAN shutdown when auto-resume is opted in", () => {
    expect(resolveInitCmd({ ...base, wasUncleanShutdown: true })).toBe(CONTINUE_OR_FRESH);
  });

  it("does NOT silently resume on a crash when the toggle is off (the banner offers it instead)", () => {
    expect(resolveInitCmd({ ...base, wasUncleanShutdown: true, autoResumeClaude: false })).toBe("");
  });

  it("resumes on an explicit banner restore, regardless of the toggle or shutdown kind", () => {
    expect(resolveInitCmd({ ...base, autoResumeClaude: false, wasUncleanShutdown: false, restoreRequested: true }))
      .toBe(CONTINUE_OR_FRESH);
  });

  it("yields to startupPrompt — triage/fleet kickoff drives its own claude launch", () => {
    expect(resolveInitCmd({ ...base, startupPrompt: "triage the issues", wasUncleanShutdown: true })).toBe("");
  });

  // REVERSED by #a-session-with-history-always-resumes. This used to assert `""` on the reasoning
  // that "an empty startup prompt still means the caller is using the prompt channel" — but an empty
  // prompt is discarded by `plan_launch`'s own `filter(|s| !s.is_empty())`, so the pane got neither a
  // baked prompt NOR an init cmd and came up as a bare shell. The prompt channel with nothing in it
  // is not a launch; deferring to the resume is.
  it("an EMPTY startup prompt does not swallow the launch — the resume answers instead", () => {
    expect(resolveInitCmd({ ...base, startupPrompt: "", restoreRequested: true })).toBe(CONTINUE_OR_FRESH);
    // …and with nothing to resume either, it is still a plain shell.
    expect(resolveInitCmd({ ...base, startupPrompt: "" })).toBe("");
  });

  it("an explicit initCmd wins over everything — internal callers know best", () => {
    expect(resolveInitCmd({ ...base, explicit: "echo hi", startupPrompt: "triage", restoreRequested: true })).toBe("echo hi");
  });
});

describe("resolveInitCmd — fleet/triage resume (#3928)", () => {
  const base = {
    explicit: undefined as string | undefined,
    startupPrompt: undefined as string | undefined,
    continueSession: false,
    paneWasClaude: true,
    autoResumeClaude: false,
    wasUncleanShutdown: false,
    restoreRequested: false,
  };

  it("RESUMES an explicitly-continued fleet pane on a clean restart — the #3928 regression", () => {
    // Without this the flag died between layers: `paneContinue` was set and forwarded to Rust, but
    // `plan_launch` only reads it on the PROMPT arm, so a resume (which carries no startup prompt)
    // fell through to LaunchPlan::None — a bare bash shell, `has_history=true · resumed=false`.
    expect(resolveInitCmd({ ...base, continueSession: true })).toBe(CONTINUE_OR_FRESH);
  });

  it("DOES start a pane that never ran claude — the premise of the old guard is gone (#3986)", () => {
    // This asserted `""` under #3928, on the reasoning "there is no conversation to resume". That was
    // true when `--continue` was emitted bare and would exit 1 on a pane with no history. #3937 made
    // the command degrade (`--continue … || claude`), so a missing conversation now starts a fresh
    // session — and the guard became a deadlock instead of a safeguard: `paneWasClaude` is set only
    // when claude STARTS, so requiring it blocked the launch that would have set it. 77 of 78 fleet
    // panes were stuck there.
    expect(resolveInitCmd({ ...base, continueSession: true, paneWasClaude: false })).toBe(CONTINUE_OR_FRESH);
  });

  it("a KICKOFF still wins — the prompt-baked path must not become a --continue", () => {
    // A startup prompt means claude launches WITH that prompt; layering --continue on top would
    // spawn a second claude before the first finished initialising.
    expect(resolveInitCmd({ ...base, continueSession: true, startupPrompt: "kickoff" })).toBe("");
  });

  it("an explicit init_cmd still outranks everything", () => {
    expect(resolveInitCmd({ ...base, continueSession: true, explicit: "npm run dev" })).toBe("npm run dev");
  });

  it("leaves #1041 intact — no continueSession, clean quit ⇒ still dormant", () => {
    expect(resolveInitCmd({ ...base, autoResumeClaude: true })).toBe("");
  });
});

describe("resolveInitCmd — the --continue fallback (#3937)", () => {
  const base = {
    explicit: undefined as string | undefined,
    startupPrompt: undefined as string | undefined,
    continueSession: false,
    paneWasClaude: false,
    autoResumeClaude: false,
    wasUncleanShutdown: false,
    restoreRequested: false,
  };

  it("NEVER emits a bare `claude --continue` — a missing conversation would leave a dead prompt", () => {
    // `plan_launch`'s history guard only covers the PROMPT arm; an init cmd goes down the INIT arm
    // verbatim. So the degrade has to live in the command itself, not in Rust's launch decision.
    const cmds = [
      resolveInitCmd({ ...base, continueSession: true, paneWasClaude: true }),
      resolveInitCmd({ ...base, paneWasClaude: true, restoreRequested: true }),
      resolveInitCmd({ ...base, paneWasClaude: true, autoResumeClaude: true, wasUncleanShutdown: true }),
    ];
    for (const c of cmds) {
      expect(c).not.toBe("claude --continue");
      expect(c).toContain("|| claude");
    }
  });

  it("an explicit initCmd is still passed through untouched", () => {
    // The override is the caller's business — we must not append a fallback to someone else's command.
    expect(resolveInitCmd({ ...base, explicit: "npm run dev", continueSession: true, paneWasClaude: true }))
      .toBe("npm run dev");
  });

  it("a kickoff (startupPrompt) still wins and emits nothing", () => {
    expect(resolveInitCmd({ ...base, startupPrompt: "go", continueSession: true, paneWasClaude: true })).toBe("");
  });
});

describe("resume does not require a prior claude run (#3986)", () => {
  const base = {
    explicit: undefined as string | undefined,
    startupPrompt: undefined as string | undefined,
    continueSession: false,
    paneWasClaude: false,
    autoResumeClaude: false,
    wasUncleanShutdown: false,
    restoreRequested: false,
  };

  it("starts claude in a pane where it has NEVER run — the deadlock", () => {
    // `paneWasClaude` is set only when claude actually starts, so requiring it meant the gate blocked
    // the very launch that would have set it. Measured: 77 of 78 fleet panes had no `paneWasClaude`,
    // i.e. Resume could not start an agent in any of them.
    expect(resolveInitCmd({ ...base, continueSession: true, paneWasClaude: false }))
      .toBe("claude --continue 2>/dev/null || claude");
  });

  it("still resumes a pane that HAS run claude", () => {
    expect(resolveInitCmd({ ...base, continueSession: true, paneWasClaude: true }))
      .toBe("claude --continue 2>/dev/null || claude");
  });

  it("a no-history pane starts FRESH rather than failing", () => {
    // What made dropping the guard safe: the command degrades on its own (#3937).
    expect(resolveInitCmd({ ...base, continueSession: true })).toContain("|| claude");
  });

  it("does nothing without continueSession — resume is opt-in per pane", () => {
    expect(resolveInitCmd({ ...base, continueSession: false, paneWasClaude: true })).toBe("");
  });

  it("a kickoff still wins over resume", () => {
    expect(resolveInitCmd({ ...base, startupPrompt: "go", continueSession: true })).toBe("");
  });

  it("CRASH recovery still requires paneWasClaude", () => {
    // The flag stays where the question it answers is the real one: after an unclean shutdown, "was
    // this ever a claude pane?" genuinely governs whether to restore it.
    expect(resolveInitCmd({ ...base, paneWasClaude: false, restoreRequested: true })).toBe("");
    expect(resolveInitCmd({ ...base, paneWasClaude: true, restoreRequested: true }))
      .toBe("claude --continue 2>/dev/null || claude");
  });
});

/**
 * THE HARNESS PLACEHOLDER (#a-session-with-history-always-resumes).
 *
 * `fleetStartProject` and `wakePane` both store the literal string `"claude"` as a pane's `initCmd`.
 * That is a PLACEHOLDER meaning "this pane runs an agent", not a command the user chose — but the
 * `explicit` arm won unconditionally, ahead of every resume branch, so a pane that was being resumed
 * opened a brand-new conversation with the old one sitting right there on disk.
 *
 * MEASURED on `network-monitor:domain-model-and-adapter-traits`: five conversations in its cage, and
 * a worker re-deriving work it had already done.
 */
describe("resolveInitCmd — a placeholder never beats a resume", () => {
  const base = {
    explicit: undefined as string | undefined,
    startupPrompt: undefined as string | undefined,
    continueSession: false,
    paneWasClaude: false,
    autoResumeClaude: false,
    wasUncleanShutdown: false,
    restoreRequested: false,
  };

  it("upgrades the bare `claude` placeholder to a resume when the pane is being resumed", () => {
    expect(resolveInitCmd({ ...base, explicit: "claude", continueSession: true })).toBe(CONTINUE_OR_FRESH);
  });

  it("upgrades it on a banner restore too — the same placeholder, the same question", () => {
    expect(resolveInitCmd({ ...base, explicit: "claude", paneWasClaude: true, restoreRequested: true }))
      .toBe(CONTINUE_OR_FRESH);
  });

  // CHANGED DELIBERATELY (`a-woken-worker-honours-its-local-model`). This asserted CONTINUE_OR_FRESH —
  // claude's command — for a bsc-agent pane, which is precisely the bug: a fleet stream wired to a
  // local model resumed by launching CLAUDE, and the configured model was never reached. The
  // placeholder names the harness, so the resume command is derived from it now.
  it("covers the bsc-agent harness, resuming it on ITS OWN command and not claude's", () => {
    expect(resolveInitCmd({ ...base, explicit: "bsc-agent", continueSession: true }))
      .toBe("bsc-agent --continue 2>/dev/null || bsc-agent");
  });

  it("tolerates surrounding whitespace — the placeholder is still a placeholder", () => {
    expect(resolveInitCmd({ ...base, explicit: "  claude  ", continueSession: true })).toBe(CONTINUE_OR_FRESH);
  });

  it("leaves a REAL override alone, even on a resume — flags mean the caller chose it", () => {
    // The exact-match set exists for this: a prefix test would have swallowed every one of these.
    for (const cmd of ["claude --dangerously-skip-permissions", "npm run dev", "aider --message go", "claude-wrapper"]) {
      expect(resolveInitCmd({ ...base, explicit: cmd, continueSession: true })).toBe(cmd);
    }
  });

  it("passes the placeholder through UNCHANGED when nothing is being resumed", () => {
    // A first launch has no conversation to continue, so the pane starts the agent plainly — this is
    // what keeps a fresh fleet start from claiming to resume something that does not exist.
    expect(resolveInitCmd({ ...base, explicit: "claude" })).toBe("claude");
  });

  it("still starts NOTHING on a plain mount — the app never launches on its own", () => {
    // The half of the rule that did not change (`only-the-user-resumes-a-session`): with no explicit
    // cmd, no prompt and no resume signal, a mount is a shell.
    expect(resolveInitCmd({ ...base, paneWasClaude: true })).toBe("");
  });
});

import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "@/store";
import { resolveInitCmd } from "@/app/console/lib/resumeClaude";

/**
 * #36: paneWasClaude + autoResumeClaude carry the "claude was running here"
 * signal across app restarts. Persistence itself is handled by zustand's
 * persist middleware — what we pin here is the in-memory contract that
 * TerminalView writes to and resolveInitCmd reads from.
 */
describe("paneWasClaude / autoResumeClaude (#36)", () => {
  beforeEach(() => {
    useAppStore.setState({ paneWasClaude: {}, autoResumeClaude: true });
  });

  it("setPaneWasClaude(pid, true) records the pane as having used claude", () => {
    useAppStore.getState().setPaneWasClaude("t0p0", true);
    expect(useAppStore.getState().paneWasClaude["t0p0"]).toBe(true);
  });

  it("setPaneWasClaude(pid, false) clears it (so an opt-out / unset case is representable)", () => {
    useAppStore.setState({ paneWasClaude: { t0p0: true, t1p2: true } });
    useAppStore.getState().setPaneWasClaude("t0p0", false);
    const state = useAppStore.getState().paneWasClaude;
    expect(state["t0p0"]).toBeUndefined();
    expect(state["t1p2"]).toBe(true);
  });

  it("setPaneWasClaude is a no-op when the flag already matches (avoids store churn on repeated OSC 100 'run')", () => {
    useAppStore.setState({ paneWasClaude: { t0p0: true } });
    const before = useAppStore.getState().paneWasClaude;
    useAppStore.getState().setPaneWasClaude("t0p0", true);
    const after = useAppStore.getState().paneWasClaude;
    // Same object reference — selectors subscribed to paneWasClaude don't re-fire.
    expect(after).toBe(before);
  });

  it("autoResumeClaude defaults to FALSE — the app never resumes a session on its own", () => {
    // #restart-does-not-resume-sessions. It used to default TRUE, so after any unclean shutdown (a kill
    // or force-quit — the normal case in development) every pane that had run Claude relaunched itself
    // with no click. The same flag also hid the crash banner, so the app started the sessions AND hid
    // the control for starting them. The mechanism is intact and the toggle still turns it back on;
    // only the default moved. Assert on a FRESH store, not the beforeEach state.
    useAppStore.setState({ autoResumeClaude: useAppStore.getInitialState().autoResumeClaude });
    expect(useAppStore.getState().autoResumeClaude).toBe(false);
  });

  it("setAutoResumeClaude flips the toggle", () => {
    useAppStore.getState().setAutoResumeClaude(false);
    expect(useAppStore.getState().autoResumeClaude).toBe(false);
    useAppStore.getState().setAutoResumeClaude(true);
    expect(useAppStore.getState().autoResumeClaude).toBe(true);
  });
});

/**
 * The composition that actually matters (#restart-does-not-resume-sessions): the store's DEFAULT,
 * fed through the real decision function, must produce no resume after an unclean shutdown.
 *
 * The two halves are pinned separately above and in resumeClaude.test.ts, but neither alone catches
 * the regression that reintroduces this bug — flipping the default back to `true`. That change keeps
 * every other test green, because they all pass the flag in explicitly.
 */
describe("the default posture resumes nothing (#restart-does-not-resume-sessions)", () => {
  it("a crashed pane that had claude does NOT auto-resume under the shipped default", () => {
    const autoResumeClaude = useAppStore.getInitialState().autoResumeClaude;
    expect(resolveInitCmd({
      explicit: undefined,
      startupPrompt: undefined,
      continueSession: false,
      paneWasClaude: true,
      autoResumeClaude,
      wasUncleanShutdown: true,
      restoreRequested: false,
    })).toBe("");
  });

  it("...and the SAME pane resumes the moment the user clicks Restore", () => {
    expect(resolveInitCmd({
      explicit: undefined,
      startupPrompt: undefined,
      continueSession: false,
      paneWasClaude: true,
      autoResumeClaude: useAppStore.getInitialState().autoResumeClaude,
      wasUncleanShutdown: true,
      restoreRequested: true,
    })).not.toBe("");
  });
});

