/**
 * Decide which command (if any) to bake into a fresh PTY shell at pane mount.
 *
 * Inputs cover the three layered intents:
 *  - `explicit`: a per-pane `initCmd` override (used by the triage flow before
 *    it moved to `startupPrompt`, and still legal for internal callers).
 *  - `startupPrompt`: when set (triage / fleet kickoff), `pty_create`'s backend
 *    handles the claude launch with the baked prompt — we must NOT also inject
 *    `claude --continue` as init_cmd, or we'd race two claude invocations.
 *  - `paneWasClaude` + `autoResumeClaude` + `wasUncleanShutdown` + `restoreRequested`:
 *    the resume path (#36/#1041). Mount the pane straight into `claude --continue` so
 *    the prior conversation resumes — but ONLY as crash recovery: a clean quit leaves
 *    sessions dormant. Resume when the user clicked "restore" in the crash banner
 *    (`restoreRequested`), OR when they've opted into silent auto-resume
 *    (`autoResumeClaude`) AND the last shutdown was unclean (`wasUncleanShutdown`).
 *    #3937: the `--continue` is emitted with a `|| claude` SHELL fallback. The Rust-side history
 *    guard (#124) lives on `plan_launch`'s PROMPT arm only — the INIT arm (which is what an init
 *    cmd like this takes) passes the string verbatim, so the guard never applied here despite this
 *    doc once claiming it did. A `claude --continue` with no conversation exits 1 having written
 *    ZERO bytes to stdout, which is why a resumed pane looked like a dead `$` prompt rather than a
 *    failed command. The fallback starts a fresh session instead, and works regardless of who is
 *    right about whether history exists.
 *
 * RESUME IS THE PREFERRED MODEL (#a-session-with-history-always-resumes). The maintainer's rule
 * splits in two, and only the first half was ever the ask in `only-the-user-resumes-a-session` /
 * `restart-does-not-resume-sessions`:
 *   - WHETHER a session starts is the user's click (or a director's wake). A restart still leaves a
 *     shell, and nothing below changes that: with no resume signal this still returns "".
 *   - HOW it starts, once something legitimately starts it, is ALWAYS a resume when there is a
 *     conversation to resume. Starting fresh beside an existing one throws away everything the
 *     agent had learned, which is most of what makes a relaunch look like a session that was
 *     killed for no reason.
 */

// #3998: the command itself now lives in `shared/lib/session/ensureClaudeRunning`, because a resume
// can reach a pane by either of two routes — this mount-time launch path, or a direct write into an
// already-live shell (the launch path is unreachable for a pane whose PTY exists). Both must emit the
// byte-identical command, so there is one definition.
import { CONTINUE_OR_FRESH, continueOrFresh } from "@/shared/lib/session/ensureClaudeRunning";

/** The bare harness launch every agent pane stores as its `initCmd`.
 *
 *  `fleetStartProject` and `wakePane` both write the literal string `"claude"`, so for an agent pane
 *  `explicit` is a PLACEHOLDER meaning "this pane runs an agent" — never a command the user chose.
 *  It nonetheless won unconditionally, ahead of every resume branch below, so a pane that was being
 *  RESUMED opened a brand-new conversation with the old one sitting right there.
 *
 *  An exact-match set rather than a prefix test, on purpose: a real override carries flags or a
 *  different program (`aider --message ...`, a wrapper script) and must still win untouched. The
 *  `--model` flag is added by the backend, not here, so a placeholder never carries one. */
// NO explicit generic annotation here, deliberately: `emit-records` chooses the emitted
// extension by scanning for an angle-bracketed identifier, so a `ReadonlySet` type argument
// reads as JSX and this module is written as `.tsx`. That silently breaks the packaged kit's
// runtime closure, which lists this module by its `.ts` path — a green typecheck and four red
// kit tests. The inferred type is identical.
const HARNESS_PLACEHOLDERS = new Set(["claude", "bsc-agent"]);

/** Is `cmd` the bare harness placeholder rather than a command the caller actually chose? */
function isHarnessPlaceholder(cmd: string): boolean {
  return HARNESS_PLACEHOLDERS.has(cmd.trim());
}

/** Does a pane running `providerId` RESUME through this module's rule?
 *
 *  Exported so `resolveEffectiveInitCmd` routes on one list instead of on "is this Claude". A harness
 *  is in {@link HARNESS_PLACEHOLDERS} exactly when a pane stores its bare name as `initCmd`, which is
 *  exactly when that name must become `<harness> --continue` on a resume — so the same set answers
 *  both questions and a third resuming harness is one edit.
 *
 *  IT USED TO BE `isClaudeProvider`, and that made the whole rule Claude-only. `bsc-agent` declares
 *  `isClaude: false`, so a resuming local worker took the branch that returns its `initCmd` verbatim —
 *  the bare harness name — and opened a brand-new conversation beside the one it meant to rejoin. The
 *  #173 fix inside `resolveInitCmd` derives the resume form FROM the placeholder precisely so that
 *  cannot happen, and it was unreachable for the only harness that needed it.
 *
 *  Aider and any other provider stay OUT: they build their own launch command with flags
 *  (`aider --model … --message …`), which is a different question this module does not answer.
 *
 *  TOLERANT OF AN ABSENT ID, for the same reason as the optional chaining below (#3934): this sits
 *  directly on the pane-launch path, where a missing field must not ABORT the launch. An unknown or
 *  absent harness answers `false` and takes the provider's own branch — which is exactly the
 *  behaviour every non-resuming provider already has, so the degraded case is the status quo rather
 *  than a new one. */
export function harnessResumes(providerId: string | undefined): boolean {
  return isHarnessPlaceholder(providerId ?? "");
}
export function resolveInitCmd(args: {
  explicit: string | undefined;
  startupPrompt: string | undefined;
  /** The pane was launched by a fleet/triage RESUME (`paneContinue`, #3928) — it should pick its
   *  conversation back up. Distinct from the crash-recovery flags below: this is an explicit,
   *  user-initiated resume of a session we know existed, not a guess after an unclean shutdown. */
  continueSession: boolean;
  paneWasClaude: boolean;
  autoResumeClaude: boolean;
  wasUncleanShutdown: boolean;
  restoreRequested: boolean;
}): string {
  const { explicit, startupPrompt, continueSession, paneWasClaude, autoResumeClaude, wasUncleanShutdown, restoreRequested } = args;
  // IS THIS LAUNCH A RESUME? Hoisted so the question is asked once and every branch agrees on the
  // answer — the `explicit` arm below used to be decided before it was ever asked. The three signals
  // are exactly the ones that were already here: an explicit fleet/triage resume (#3928/#3986), the
  // crash banner's Restore click, and the opt-in silent auto-resume after an unclean shutdown
  // (#1041, off by default since `restart-does-not-resume-sessions`). No NEW way to resume is
  // introduced, so the app still starts nothing on its own.
  const resuming = continueSession
    || (paneWasClaude && (restoreRequested || (autoResumeClaude && wasUncleanShutdown)));
  // Explicit overrides win — caller knows best — EXCEPT when the "override" is the bare harness
  // placeholder every agent pane carries AND this launch is a resume (see `HARNESS_PLACEHOLDERS`).
  // Returning it verbatim there is how a resumed worker came back to an empty conversation.
  if (explicit && explicit.length > 0) {
    // The placeholder IS the harness name (`claude` / `bsc-agent`), so the resume command is derived
    // from it rather than assumed. Before this, a resuming `bsc-agent` pane — a stream wired to a
    // local model — returned claude's command and launched CLAUDE, silently ignoring the model.
    return resuming && isHarnessPlaceholder(explicit) ? continueOrFresh(explicit) : explicit;
  }
  // Triage / fleet launches claude via the prompt-baked path; layering an
  // init_cmd on top would spawn a second claude before the first finishes
  // initialising.
  //
  // TRUTHY, not `!== undefined`: that also caught the empty string, and an empty prompt reaches
  // `plan_launch` as `Some("")`, which its own `filter(|s| !s.is_empty())` discards — so the pane got
  // neither a baked prompt nor an init cmd and came up as a bare shell. Falling through lets the
  // resume branch below answer instead, which is what an empty prompt wants.
  if (startupPrompt) return "";
  // #3928: an explicit fleet/triage RESUME. Without this the flag died in the gap between layers —
  // `fleetStartProject` set `paneContinue`, `TerminalView` forwarded it as `continueSession`, and
  // `plan_launch` then discarded it, because it only reads that flag on the PROMPT arm. A resume
  // carries no startup prompt (that's a kickoff), so the plan fell through to `None` and the pane
  // came up as a bare bash shell: `has_history=true · resumed=false`. Every fleet relaunch was
  // silently starting cold. Placed AFTER the startupPrompt branch so a kickoff still wins.
  // #3986: `continueSession` ALONE. This used to require `paneWasClaude` too, which deadlocked: that
  // flag is set only when claude actually starts (the `claude()` wrapper's OSC 100 `run`), so a pane
  // where claude had never started could never be resumed INTO claude — the gate blocked the launch,
  // the launch was what would have set the flag. Measured: 77 of 78 fleet panes had no
  // `paneWasClaude`, i.e. Resume could not start an agent in any of them, which is the whole of the
  // "sessions come up as bare shells" thread.
  //
  // Safe to drop on both sides. `continueSession` comes from `paneContinue`, set by
  // `fleetStartProject` for FLEET panes, and the call site already forces it false for a manual
  // console (`manual ? false : …`) — so the guard excluded nothing a manual pane needed. And
  // CONTINUE_OR_FRESH degrades on its own (`--continue … || claude`, #3937), so a pane with no prior
  // conversation starts fresh rather than failing: `paneWasClaude` was guarding a case the command
  // already handles.
  //
  // Both this and the crash-recovery path (#1041) now read the single `resuming` flag above. A clean
  // quit still auto-resumes NOTHING, because none of its three signals is set on one.
  if (resuming) return CONTINUE_OR_FRESH;
  return "";
}
